import tkinter as tk, random; root = tk.Tk(); c = tk.Canvas(root, width=400, height=400, bg='black'); c.pack(); snake, dir, food = [(10, 10), (10, 11), (10, 12)], (0, -1), (5, 5); root.bind("<Key>", lambda e: exec("global dir; nd = {'w':(0,-1),'s':(0,1),'a':(-1,0),'d':(1,0)}.get(e.char.lower()); dir = nd if nd and (nd[0]+dir[0] or nd[1]+dir[1]) else dir")); move = lambda: exec("global food; x, y = (snake[0][0] + dir[0]) % 20, (snake[0][1] + dir[1]) % 20; snake.insert(0, (x, y)); food = random.choice([(i, j) for i in range(20) for j in range(20) if (i, j) not in snake]) if (x, y) == food else (snake.pop(), food)[1]; print(f'TASK {100<<40|{(0,-1):1,(0,1):2,(-1,0):3,(1,0):4}[dir]<<36|x<<28|y<<20|food[0]<<12|food[1]<<4|len(snake):X}'); c.delete('all'); c.create_rectangle(food[0]*20, food[1]*20, food[0]*20+20, food[1]*20+20, fill='red'); [c.create_rectangle(sx*20, sy*20, sx*20+20, sy*20+20, fill='green') for sx, sy in snake]; root.after(100, move)"); move(); root.mainloop()
